import{Ct as e,at as t,it as n,ot as r,st as i,t as a,tt as o,yt as s}from"./chunks/framework.8wxrR_KU.js";var c=JSON.parse(`{"title":"Introducing Upgrading & Blog","description":"Learn why WarpDrive 5.10 added the permanent Upgrading and Blog sections to warp-drive.io and where the former /guides/migrating/ pages now live.","frontmatter":{"title":"Introducing Upgrading & Blog","description":"Learn why WarpDrive 5.10 added the permanent Upgrading and Blog sections to warp-drive.io and where the former /guides/migrating/ pages now live.","outline":{"level":"2,3"}},"headers":[],"relativePath":"blog/v5/introducing-upgrading-and-blog.md","filePath":"blog/v5/introducing-upgrading-and-blog.md"}`),l={name:`blog/v5/introducing-upgrading-and-blog.md`};function u(a,c,l,u,d,f){let p=e(`SinceBadge`);return s(),n(`div`,null,[c[0]||=o(`h1`,{id:`introducing-upgrading-blog`,tabindex:`-1`},[r(`Introducing Upgrading & Blog `),o(`a`,{class:`header-anchor`,href:`#introducing-upgrading-blog`,"aria-label":`Permalink to “Introducing Upgrading & Blog”`},`​`)],-1),i(p,{version:`5.10.0`}),c[1]||=t(` \xA0 2026-09-05<p>Guides and API docs change version to version, but some content is point-in-time: release announcements, deprecation guides, and one-off migration guides. That content needs a stable home whose URLs don&#39;t move under it.</p><p>Starting today, <a href="https://warp-drive.io" target="_blank" rel="noreferrer">warp-drive.io</a> has two new top-level sections for exactly this:</p><ul><li><strong><a href="/pr-preview/pr-11219/upgrading/">Upgrading</a></strong> — major-version upgrade guides, and eventually deprecation guidance and feature-specific migration guides, organized by major version.</li><li><strong>Blog</strong> (this section) — release posts and other announcements, dual-published here so that non-Ember consumers of <strong><em>Warp</em>Drive</strong>* don&#39;t have to go looking for them on <a href="https://blog.emberjs.com/" target="_blank" rel="noreferrer">blog.emberjs.com</a>.</li></ul><p>Both sections share the same guarantee: <strong>a published URL here is never renamed and never unpublished.</strong> If a page is fully superseded, it stays in place, is marked superseded, and links forward to whatever replaced it.</p><p>As a first step, the guides that used to live at <code>/guides/migrating/</code> have moved to <a href="/pr-preview/pr-11219/upgrading/v5/"><code>/upgrading/v5/</code></a> — their old URLs still resolve and now point readers to the new location.</p><p>This is the first piece of the plan described in <a href="https://github.com/warp-drive-data/warp-drive/issues/11028" target="_blank" rel="noreferrer">issue #11028</a>. Next up: bringing deprecation guides in from <a href="https://deprecations.emberjs.com/" target="_blank" rel="noreferrer">deprecations.emberjs.com</a> and setting up dual-publishing for release posts from <a href="https://blog.emberjs.com/" target="_blank" rel="noreferrer">blog.emberjs.com</a>.</p>`,7)])}var d=a(l,[[`render`,u]]);export{c as __pageData,d as default};